export type ProtocolName = keyof ProtocolHandlers;

/** The protocols createDelegate() consults even when you name none. */
export type DefaultProtocolName =
  | "NSApplicationDelegate"
  | "NSWindowDelegate"
  | "NSTableViewDataSource"
  | "NSTableViewDelegate"
  | "NSOutlineViewDataSource"
  | "NSOutlineViewDelegate"
  | "NSTextFieldDelegate"
  | "NSTextViewDelegate"
  | "NSTextDelegate"
  | "NSControlTextEditingDelegate"
  | "NSMenuDelegate"
  | "NSMenuItemValidation"
  | "NSSplitViewDelegate"
  | "NSToolbarDelegate"
  | "NSToolbarItemValidation"
  | "NSTabViewDelegate"
  | "NSComboBoxDelegate"
  | "NSComboBoxDataSource"
  | "NSSearchFieldDelegate"
  | "NSCollectionViewDelegate"
  | "NSCollectionViewDataSource"
  | "NSCollectionViewDelegateFlowLayout"
  | "NSDraggingDestination"
  | "NSDraggingSource"
  | "NSOpenSavePanelDelegate"
  | "NSUserInterfaceValidations";

type Intersect<U> = (U extends unknown ? (x: U) => void : never) extends
  (x: infer I) => void ? I : never;

/**
 * The handler table for a delegate, merged across every protocol that will
 * be searched for its type encodings.
 *
 *   const handlers = {
 *     windowWillClose_: () => app.quit(),
 *   } satisfies DelegateHandlers;
 *
 * `satisfies` is what you want here rather than an annotation: it checks
 * every handler and rejects a misspelled selector, while createDelegate still
 * receives a plain object of functions.
 */
export type DelegateHandlers<P extends ProtocolName = never> =
  Intersect<ProtocolHandlers[P | DefaultProtocolName]>;

/**
 * createDelegate(), typed:
 *
 *   import { createDelegate as raw } from "../objc.ts";
 *   const createDelegate = raw as unknown as CreateDelegate;
 *   const d = createDelegate(
 *     { tableView_objectValueForTableColumn_row_: (_t, _c, row) => rows[Number(row)] },
 *     { protocols: ["NSTableViewDataSource"] },
 *   );
 */
export type CreateDelegate = <P extends ProtocolName = never>(
  handlers: DelegateHandlers<P>,
  options?: {
    protocols?: readonly P[];
    types?: Record<string, string>;
    superclass?: string;
    name?: string;
  },
) => ObjCId;

